# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GELENEKSEL VE DİJİTAL TARİH ARAŞTIRMA SÜREÇLERİNİN KARŞILAŞTIRMASI</text>\n  <rect x="25" y="46" width="315" height="194" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">GELENEKSEL TARİHÇİLİK SÜRECİ</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#7c2d12">• Erişim: Fiziksel arşiv ve kütüphane ziyareti</text>\n  <text x="42" y="122" font-size="11.5" font-weight="bold" fill="#7c2d12">• Kayıt ve Tasnif: Kâğıt fişleme, katalog kartları</text>\n  <text x="42" y="148" font-size="11.5" font-weight="bold" fill="#7c2d12">• Analiz: Sınırlı sayıda belgenin yakın okuması</text>\n  <text x="42" y="174" font-size="11.5" font-weight="bold" fill="#7c2d12">• Yazım ve Sunum: Basılı eser, makale, doğrusal</text>\n  <text x="52" y="192" font-size="11" fill="#334155">(lineer) anlatı ve statik haritalar</text>\n  <text x="42" y="218" font-size="11" font-weight="bold" fill="#9a3412">• Koruma Riski: Orijinal belgenin yıpranma riski</text>\n  <rect x="360" y="46" width="315" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">DİJİTAL TARİHÇİLİK SÜRECİ</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Erişim: Çevrim içi açık arşivler ve veri tabanları</text>\n  <text x="377" y="122" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Kayıt ve Tasnif: Üst veri (metadata), OCR / HTR</text>\n  <text x="377" y="148" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Analiz: Büyük veri (Big Data), H-GIS, ağ analizi</text>\n  <text x="377" y="174" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Yazım ve Sunum: Etkileşimli harita, 3B model,</text>\n  <text x="387" y="192" font-size="11" fill="#334155">hiper-metin ve sanal müze uygulamaları</text>\n  <text x="377" y="218" font-size="11" font-weight="bold" fill="#1d4ed8">• Koruma: Fiziksel teması azaltarak aslı koruma</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DİJİTAL TARİHÇİLİKTE KULLANILAN BAŞLICA ANALİZ VE SUNUM ARAÇLARI</text>\n  <rect x="20" y="48" width="155" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="97" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">OCR / HTR VE METİN</text>\n  <text x="97" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">MADENCİLİĞİ</text>\n  <text x="30" y="114" font-size="10.5" fill="#334155">• El yazması ve matbu</text>\n  <text x="36" y="130" font-size="10.5" fill="#334155">belgeleri metne çevirir.</text>\n  <text x="30" y="154" font-size="10.5" fill="#334155">• Binlerce belgede kavram</text>\n  <text x="36" y="170" font-size="10.5" fill="#334155">sıklığı analizi yapar.</text>\n  <rect x="188" y="48" width="155" height="190" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="265" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">TARİHSEL CBS</text>\n  <text x="265" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">(H-GIS)</text>\n  <text x="198" y="114" font-size="10.5" fill="#334155">• Göç, ticaret yolu, nüfus</text>\n  <text x="204" y="130" font-size="10.5" fill="#334155">ve savaş verilerini</text>\n  <text x="204" y="146" font-size="10.5" fill="#334155">mekânsal haritalarla</text>\n  <text x="204" y="162" font-size="10.5" fill="#334155">katmanlı olarak birleştirir.</text>\n  <rect x="356" y="48" width="155" height="190" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="433" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">AĞ ANALİZİ VE</text>\n  <text x="433" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">VERİ GÖRSELLEŞTİRME</text>\n  <text x="366" y="114" font-size="10.5" fill="#334155">• Tarihsel aktörler, kentler</text>\n  <text x="372" y="130" font-size="10.5" fill="#334155">ve devletler arasındaki</text>\n  <text x="372" y="146" font-size="10.5" fill="#334155">haberleşme ve ticaret</text>\n  <text x="372" y="162" font-size="10.5" fill="#334155">ağlarını şemalaştırır.</text>\n  <rect x="524" y="48" width="155" height="190" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="601" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">3B MODELLEME VE</text>\n  <text x="601" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">SANAL MÜZECİLİK</text>\n  <text x="534" y="114" font-size="10.5" fill="#334155">• Arkeolojik sit alanlarını</text>\n  <text x="540" y="130" font-size="10.5" fill="#334155">ve tarihî eserleri</text>\n  <text x="540" y="146" font-size="10.5" fill="#334155">LiDAR ve fotogrametri ile</text>\n  <text x="540" y="162" font-size="10.5" fill="#334155">dijitalde yeniden kurar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">1. ÜNİTE SENTEZİ: TARİHSEL BİLGİNİN İNŞA SÜRECİ (5T) VE DİJİTAL DÖNÜŞÜM</text>\n  <rect x="25" y="48" width="650" height="82" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">TARİHSEL ARAŞTIRMA YÖNTEMİNİN BEŞ AŞAMASI (5T)</text>\n  <text x="45" y="98" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. TARAMA</text>\n  <text x="45" y="114" font-size="10" fill="#475569">(Kaynak Bulma)</text>\n  <text x="148" y="102" font-size="16" font-weight="bold" fill="#2563eb">➔</text>\n  <text x="172" y="98" font-size="11.5" font-weight="bold" fill="#1e3a8a">2. TASNİF</text>\n  <text x="172" y="114" font-size="10" fill="#475569">(Sınıflandırma)</text>\n  <text x="275" y="102" font-size="16" font-weight="bold" fill="#2563eb">➔</text>\n  <text x="300" y="98" font-size="11.5" font-weight="bold" fill="#1e3a8a">3. TAHLİL</text>\n  <text x="300" y="114" font-size="10" fill="#475569">(Çözümleme)</text>\n  <text x="400" y="102" font-size="16" font-weight="bold" fill="#2563eb">➔</text>\n  <text x="425" y="98" font-size="11.5" font-weight="bold" fill="#1e3a8a">4. TENKİT</text>\n  <text x="425" y="114" font-size="10" fill="#475569">(İç/Dış Eleştiri)</text>\n  <text x="530" y="102" font-size="16" font-weight="bold" fill="#2563eb">➔</text>\n  <text x="555" y="98" font-size="11.5" font-weight="bold" fill="#1e3a8a">5. TERKİP</text>\n  <text x="555" y="114" font-size="10" fill="#475569">(Sentez / Yazım)</text>\n  <rect x="25" y="145" width="315" height="95" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="167" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">DİJİTAL DÖNÜŞÜMÜN FIRSATLARI</text>\n  <text x="40" y="190" font-size="11" fill="#334155">• Küresel arşivlere hızlı ve eşit erişim</text>\n  <text x="40" y="208" font-size="11" fill="#334155">• Büyük veri, H-GIS ve 3B koruma imkânı</text>\n  <text x="40" y="226" font-size="11" fill="#334155">• Fiziksel belgelerin yıpranmasını önleme</text>\n  <rect x="360" y="145" width="315" height="95" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="167" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">RİSKLER VE ETİK SORUMLULUKLAR</text>\n  <text x="375" y="190" font-size="11" fill="#334155">• Sahte görsel/belge (deepfake) ve dezenformasyon</text>\n  <text x="375" y="208" font-size="11" fill="#334155">• Dijital kaynak tenkidi ve çapraz doğrulama</text>\n  <text x="375" y="226" font-size="11" fill="#334155">• Telif hakkı, doğru atıf ve mahremiyete saygı</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
